// 共同边界只接受选择ID/版本；玩家不能提交任意工期、目标权源或完成事实。
#include "diplomacy_integration.hpp"
namespace hanmo::resident {
namespace {
using V=BoundaryValue;
// 共同authority四字段沿原组织合同，不让玩家提交grant、钱粮或完工事实。
V authority(const ActingAuthority& a){return boundary::obj({{"organization_id",V{a.organization_id}},{"office_id",V{a.office_id}},{"authority_epoch",V{a.authority_epoch}},{"actor_id",V{a.actor_id}}});}
ActingAuthority authority(const V& v){boundary::fields(v,{"organization_id","office_id","authority_epoch","actor_id"},{},"authority");return {boundary::get_string(v,"organization_id","authority"),boundary::get_string(v,"office_id","authority"),boundary::get_int(v,"authority_epoch","authority"),boundary::get_string(v,"actor_id","authority")};}
V identity(const WorldIdentity& i){StableId hex;const char* digits="0123456789abcdef";for(auto b:i.world_id){hex+=digits[b>>4];hex+=digits[b&15];}return boundary::obj({{"world_id",V{hex}},{"execution_epoch",V{i.execution_epoch}},{"revision",V{i.revision}},{"tick",V{i.tick}}});}
WorldIdentity identity(const V& v){boundary::fields(v,{"world_id","execution_epoch","revision","tick"},{},"identity");WorldIdentity out;const auto hex=boundary::get_string(v,"world_id","identity");if(hex.size()!=32)boundary::fail("InvalidDiplomacyWorldIdentity","identity/world_id");auto nibble=[](char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:-1;};for(std::size_t n=0;n<out.world_id.size();++n){int a=nibble(hex[n*2]),b=nibble(hex[n*2+1]);if(a<0||b<0)boundary::fail("InvalidDiplomacyWorldIdentity","identity/world_id");out.world_id[n]=static_cast<std::uint8_t>(a*16+b);}out.execution_epoch=boundary::get_int(v,"execution_epoch","identity");out.revision=boundary::get_int(v,"revision","identity");out.tick=boundary::get_int(v,"tick","identity");if(out.execution_epoch<0||out.revision<0||out.tick<0)boundary::fail("InvalidDiplomacyWorldIdentity","identity");return out;}
}
BoundaryValue encode_diplomacy_command(const DiplomacyCommand& command){return std::visit([](const auto& c)->V{using T=std::decay_t<decltype(c)>;
    if constexpr(std::is_same_v<T,DiplomaticProposeCommand>)return boundary::obj({{"authority",authority(c.authority)},{"policy_id",V{c.policy_id}},{"terms_id",V{c.terms_id}}});
    else if constexpr(std::is_same_v<T,DiplomaticMissionCommand>)return boundary::obj({{"offer_id",V{c.offer_id}},{"source_fact_id",V{c.source_fact_id}},{"expected_revision",V{c.expected_revision}}});
    else if constexpr(std::is_same_v<T,DiplomaticPresentCommand>||std::is_same_v<T,DiplomaticReplyCommand>){auto value=boundary::obj({{"offer_id",V{c.offer_id}},{"source_fact_id",V{c.source_fact_id}},{"expected_revision",V{c.expected_revision}},{"terms_revision",V{c.terms_revision}}});if constexpr(std::is_same_v<T,DiplomaticReplyCommand>)value.as<V::Dict>()->emplace_back("decision",V{c.decision==DiplomaticReplyKind::accept?"accept":"refuse"});return value;}
    else if constexpr(std::is_same_v<T,DiplomaticDelegateCommand>)return boundary::obj({{"delegation_policy_id",V{c.delegation_policy_id}},{"expected_world_revision",V{c.expected_world_revision}}});
    else if constexpr(std::is_same_v<T,DiplomaticEnvoyAcceptCommand>)return boundary::obj({{"authority_fact_id",V{c.authority_fact_id}},{"expected_world_revision",V{c.expected_world_revision}}});
    else {auto value=boundary::obj({{"task_id",V{c.task_id}},{"expected_world_revision",V{c.expected_world_revision}}});if constexpr((std::is_same_v<T,DiplomaticEnvoyDeliverCommand>||std::is_same_v<T,DiplomaticEnvoyReportCommand>))value.as<V::Dict>()->emplace_back("provider_actor_id",V{c.provider_actor_id});return value;}
},command);}
Outcome<DiplomacyCommand> decode_diplomacy_command(const StableId& kind,const V& v){try{using namespace boundary;
    if(kind=="diplomatic_propose_passage"){fields(v,{"authority","policy_id","terms_id"},{},"params");return {true,DiplomaticProposeCommand{authority(field(v,"authority","params")),get_string(v,"policy_id","params"),get_string(v,"terms_id","params")},{}};}
    if(kind=="diplomatic_commission_envoy"){fields(v,{"offer_id","source_fact_id","expected_revision"},{},"params");return {true,DiplomaticMissionCommand{get_string(v,"offer_id","params"),get_string(v,"source_fact_id","params"),get_int(v,"expected_revision","params")},{}};}
    if(kind=="diplomatic_present_passage"){fields(v,{"offer_id","source_fact_id","expected_revision","terms_revision"},{},"params");return {true,DiplomaticPresentCommand{get_string(v,"offer_id","params"),get_string(v,"source_fact_id","params"),get_int(v,"expected_revision","params"),get_int(v,"terms_revision","params")},{}};}
    if(kind=="diplomatic_reply_passage"){fields(v,{"offer_id","source_fact_id","expected_revision","terms_revision","decision"},{},"params");const auto choice=get_string(v,"decision","params");if(choice!="accept"&&choice!="refuse")fail("InvalidDiplomaticReply","params/decision");return {true,DiplomaticReplyCommand{get_string(v,"offer_id","params"),get_string(v,"source_fact_id","params"),get_int(v,"expected_revision","params"),get_int(v,"terms_revision","params"),choice=="accept"?DiplomaticReplyKind::accept:DiplomaticReplyKind::refuse},{}};}
    if(kind=="envoy_accept"){fields(v,{"authority_fact_id","expected_world_revision"},{},"params");return {true,DiplomaticEnvoyAcceptCommand{get_string(v,"authority_fact_id","params"),get_int(v,"expected_world_revision","params")},{}};}
    if(kind=="envoy_deliver"){fields(v,{"task_id","provider_actor_id","expected_world_revision"},{},"params");return {true,DiplomaticEnvoyDeliverCommand{get_string(v,"task_id","params"),get_string(v,"provider_actor_id","params"),get_int(v,"expected_world_revision","params")},{}};}
    if(kind=="diplomatic_delegate_envoy"){fields(v,{"delegation_policy_id","expected_world_revision"},{},"params");return {true,DiplomaticDelegateCommand{get_string(v,"delegation_policy_id","params"),get_int(v,"expected_world_revision","params")},{}};}
    if(kind=="envoy_report"){fields(v,{"task_id","provider_actor_id","expected_world_revision"},{},"params");return {true,DiplomaticEnvoyReportCommand{get_string(v,"task_id","params"),get_string(v,"provider_actor_id","params"),get_int(v,"expected_world_revision","params")},{}};}
    if(kind=="envoy_cancel"){fields(v,{"task_id","expected_world_revision"},{},"params");return {true,DiplomaticEnvoyCancelCommand{get_string(v,"task_id","params"),get_int(v,"expected_world_revision","params")},{}};}
    return {false,{},common_failure("UnsupportedDiplomacyCommand",kind,ErrorKind::unsupported_capability).error};
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_diplomacy_quote(const DiplomacyQuote& q){return boundary::obj({{"identity",identity(q.identity)},{"actor_id",V{q.actor_id}},{"duration",V{q.duration}},{"command_kind",V{diplomacy_command_kind(q.command)}},{"command",encode_diplomacy_command(q.command)}});}
Outcome<DiplomacyQuote> decode_diplomacy_quote(const V& v){try{using namespace boundary;fields(v,{"identity","actor_id","duration","command_kind","command"},{},"quote");DiplomacyQuote q;q.identity=identity(field(v,"identity","quote"));q.actor_id=get_string(v,"actor_id","quote");q.duration=get_int(v,"duration","quote");auto command=decode_diplomacy_command(get_string(v,"command_kind","quote"),field(v,"command","quote"));if(!command.ok)return {false,{},command.error};q.command=std::move(command.value);if(q.actor_id.empty()||((std::holds_alternative<DiplomaticEnvoyDeliverCommand>(q.command)||std::holds_alternative<DiplomaticEnvoyReportCommand>(q.command))?q.duration<1:q.duration!=0))fail("InvalidDiplomacyQuote","quote");return {true,std::move(q),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
